<?php namespace App\Http\Controllers; use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller {public function index(Request $r){$customers=Customer::when($r->q,fn($q,$v)=>$q->where('full_name','like','%'.$v.'%')->orWhere('phone','like','%'.$v.'%'))->latest()->paginate(15);return view('customers.index',compact('customers'));} public function create(){return view('customers.create');} public function store(Request $r){$d=$r->validate(['full_name'=>'required','phone'=>'required','email'=>'nullable|email','address'=>'nullable']);$d['business_id']=auth()->user()->business_id;$d['customer_code']='CUS-'.now()->format('Y').'-'.str_pad((string)(Customer::max('id')+1),6,'0',STR_PAD_LEFT);$c=Customer::create($d);return redirect()->route('customers.show',$c)->with('success','Customer created.');} public function show(Customer $customer){$customer->load('vehicles','jobs','invoices');return view('customers.show',compact('customer'));} public function edit(Customer $customer){return view('customers.edit',compact('customer'));} public function update(Request $r,Customer $customer){$customer->update($r->validate(['full_name'=>'required','phone'=>'required','email'=>'nullable|email','address'=>'nullable']));return back()->with('success','Customer updated.');} public function destroy(Customer $customer){abort(405);}}
